@font-face {
    font-family: "MyCustomFont";
    src: url("https://erpnext.ivalueconsult.com/files/DINNextLTArabic-Regular.ttf") format("opentype");
}

* {
    font-family: "MyCustomFont" !important;
    box-sizing: border-box;
}

@page {
    size: A4;
    margin: 12mm;
}

html, body {
    margin: 0;
    padding: 0;
}

.page {
    width: 100%;
    page-break-before: always;
    page-break-after: always;
    break-before: page;
    break-after: page;
}

.page:first-of-type {
    page-break-before: auto;
    break-before: auto;
}

.page:last-of-type {
    page-break-after: auto;
    break-after: auto;
}

.header {
    margin-top: 10px;
    margin-bottom: 10px;
}

.footer {
    margin-top: 10px;
}

.header img,
.footer img {
    width: 100%;
    height: auto;
    display: block;
}

.center {
    text-align: center;
    font-weight: bold;
}

.right {
    text-align: right;
    font-weight: bold;
}

.amount {
    text-align: center;
    white-space: nowrap;
}

.title-ar {
    font-weight: bold;
    font-size: 16px;
    margin-top: 4px;
}

.title-en {
    font-weight: bold;
    font-size: 18px;
    margin-bottom: 6px;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th,
td {
    border: 1px solid #2b66c7;
    padding: 5px 7px;
    vertical-align: middle;
    font-size: 10.5px;
    text-align: center;
    font-weight: bold;
}

.head-row th {
    background: #0e2a57;
    color: #fff;
    font-weight: 700;
    font-size: 12px;
    text-align: center;
}

.muted {
    color: #6b7280;
}

.net-bar td {
    background: #0e2a57;
    color: #fff;
    font-weight: bold;
    text-align: center;
    font-size: 13px;
}

.stamp-wrap {
    display: flex;
    justify-content: flex-end;
    margin-top: 10px;
}

.stamp-wrap img {
    width: 120px;
}

.iban {
    margin-top: 10px;
    font-size: 13px;
}

.money-line {
    direction: rtl;
    unicode-bidi: embed;
}

.money-line .amount {
    direction: ltr;
    unicode-bidi: isolate;
    margin-left: 6px;
    color: white;
}

.money-line .currency {
    margin-left: 6px;
    color: white;
}

.money-line .only {
    margin-right: 6px;
    font-weight: 600;
    color: white;
}

.empty-line {
    color: #999;
    letter-spacing: 2px;
    font-weight: bold;
}

.financial-block {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.financial-table {
    width: 100%;
    border-collapse: collapse;
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.financial-table tr,
.financial-table td,
.financial-table th,
.stamp-wrap,
.iban {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.financial-table th,
.financial-table td {
    font-size: 10px;
    padding: 5px 6px;
}

.clearance-one-page {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
    font-size: 10px;
    line-height: 1.35;
}

.clearance-one-page p,
.clearance-one-page div,
.clearance-one-page table,
.clearance-one-page tr,
.clearance-one-page td,
.clearance-one-page span {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.clearance-one-page p {
    margin-top: 0 !important;
    margin-bottom: 6px !important;
}

.clearance-one-page h1,
.clearance-one-page h2,
.clearance-one-page h3,
.clearance-one-page h4,
.clearance-one-page .title-ar,
.clearance-one-page .title-en {
    margin-top: 2px !important;
    margin-bottom: 4px !important;
}
